import{_ as o,o as r,c as n,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Hyperconvergence Using Proxmox and Ceph; A Journey Through Data and Time - Iztok Gregori","description":"","frontmatter":{"title":"Hyperconvergence Using Proxmox and Ceph; A Journey Through Data and Time - Iztok Gregori","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Proxmox","Ceph","Hyperconvergence","Storage Infrastructure","Open-source"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Hyperconvergence_Using_Proxmox_and_Ceph_A_Journey_Through_Data_and_Time_-_Iztok_Gregori.md","filePath":"posts/2025/Hyperconvergence_Using_Proxmox_and_Ceph_A_Journey_Through_Data_and_Time_-_Iztok_Gregori.md","lastUpdated":1780459816000}'),_={name:"posts/2025/Hyperconvergence_Using_Proxmox_and_Ceph_A_Journey_Through_Data_and_Time_-_Iztok_Gregori.md"};function a(i,e,p,g,s,l){return r(),n("div",null,[...e[0]||(e[0]=[t("<p>在本次会议中，Linux系统管理员和Proxmox及Ceph用户Iztok Gregori分享了他在使用了Proxmox和Ceph进行超融合存储方面的实践经验。</p><p><strong>主要议题</strong>：</p><ol><li><strong>Hyper Convergence介绍</strong>：Hyper Convergence是一种将虚拟化、存储和网络集成在单一节点上的软件定义基础设施，通过多个节点的集群化运行，实现高可用性和易于管理。</li><li><strong>Proxmox和Ceph的结合</strong>：Proxmox作为虚拟化平台，支持KVM虚拟机和LXC容器，而Ceph作为存储系统，支持对象存储、块存储和文件系统存储，具备高可用性和扩展性。</li><li><strong>Elettra的Ceph集群实践</strong>：Elettra是一个多学科研究中心，位于意大利，使用Proxmox和Ceph构建了超融合集群，用于存储科学数据和企业应用程序。</li><li><strong>遇到的问题和解决方案</strong>：在实践过程中，遇到了Zimbra与Ceph不兼容、虚拟机性能问题和网络问题等。通过将Zimbra迁移到RBD存储、升级硬件和优化网络配置等手段解决了这些问题。</li><li><strong>未来计划</strong>：计划升级硬件、部署独立的Ceph RGW集群，并继续优化硬件和网络配置。</li></ol><p><strong>关键细节</strong>：</p><ul><li>Elettra的Ceph集群从最初的8节点扩展到16节点，并增加了SSD存储。</li><li>遇到的网络问题是主要挑战，建议将Proxmox和Ceph网络隔离。</li><li>为Ceph预留足够的资源，避免过度分配给虚拟化。</li><li>Proxmox的API可以与其他工具集成，但目前没有实现多租户的资源配额管理。</li></ul><p>通过本次分享，Iztok Gregori强调了Hyper Convergence的优势，同时也指出了实施过程中可能遇到的挑战和解决方案。</p>",6)])])}const x=o(_,[["render",a]]);export{h as __pageData,x as default};
